      'function validarUsuario(body) {\n  const erros = [];\n  if (typeof body.nome !== "string" || body.nome.trim() === "") erros.push({ campo: "nome", mensagem: "obrigatório" });\n  if (typeof body.email !== "string" || !body.email.includes("@")) erros.push({ campo: "email", mensagem: "inválido" });\n  if (body.idade !== undefined && !(Number.isInteger(body.idade) && body.idade >= 0)) erros.push({ campo: "idade", mensagem: "inválida" });\n  return erros;\n}',
